import CryptoKit
import XCTest
@testable import OpenDisplay

final class RecordCodecTests: XCTestCase {
    private let keys = Handshake.sessionKeys(key: SymmetricKey(data: Vectors.pairingKey), c: Vectors.c, s: Vectors.s)

    /// Byte-exact records generated by work/ipad-vectors/vectors.swift from raw CryptoKit calls.
    private let clientHelloRecord = hexData(
        "0000006e00000000000000009c7dec78abe7176f423c9f4553e34c985938928092500d57d442f832f71788e4c005bd17"
        + "a2fb5a3aa0552ae7ce1a832206f8c5e2b55be533785c7796af6e3b0fda4cf2475ef151adb866206399101307e0306aa8"
        + "81d16b5b8889fea3da113204bebeb86c7c00")
    private let serverHeartbeat0 = hexData("0000001d00000000000000000af1aeafbcaa44ab715ff644427096cc3a9bee890f")
    private let serverHeartbeat1 = hexData("0000001c0000000000000001fd1638697d5039f0d74fe56b2dadb70e0c6df766")

    func testSealerMatchesIndependentVectors() throws {
        var sealer = RecordSealer(key: keys.send)
        XCTAssertEqual(try sealer.seal(type: 4, payload: Data([0xDE, 0xAD, 0xBE, 0xEF])), serverHeartbeat0)
        XCTAssertEqual(try sealer.seal(type: 4, payload: Data([0x01, 0x02, 0x03])), serverHeartbeat1)
        XCTAssertEqual(sealer.nextSequence, 2)
    }

    func testOpenerReadsIndependentWindowsHelloRecord() throws {
        let length = try XCTUnwrap(RecordFormat.bodyLength(fromPrefix: clientHelloRecord.prefix(4)))
        XCTAssertEqual(length, clientHelloRecord.count - 4)

        var opener = RecordOpener(key: keys.receive)
        let record = try opener.open(body: clientHelloRecord.dropFirst(4))
        XCTAssertEqual(record.type, RecordType.hello.rawValue)

        let hello = try XCTUnwrap(WindowsHello.decode(record.payload))
        XCTAssertEqual(hello, WindowsHello(name: "PC", width: 1600, height: 1000, fps: 30, transport: "USB", ipadEdge: "left"))
        XCTAssertEqual(hello.connectionKind, .usb)
        XCTAssertEqual(opener.expectedSequence, 1)
    }

    func testRoundTripAcrossManyRecords() throws {
        var sealer = RecordSealer(key: keys.receive)
        var opener = RecordOpener(key: keys.receive)
        for index in 0..<100 {
            let payload = Data((0..<(index * 37)).map { UInt8(truncatingIfNeeded: $0 &* 31 &+ index) })
            let record = try sealer.seal(type: 2, payload: payload)
            let length = try XCTUnwrap(RecordFormat.bodyLength(fromPrefix: record.prefix(4)))
            XCTAssertEqual(length, record.count - 4)
            let opened = try opener.open(body: record.dropFirst(4))
            XCTAssertEqual(opened.type, 2)
            XCTAssertEqual(opened.payload, payload)
        }
    }

    func testRejectsReplayedAndSkippedSequences() throws {
        var sealer = RecordSealer(key: keys.receive)
        let first = try sealer.seal(type: 4, payload: Data([1]))
        let second = try sealer.seal(type: 4, payload: Data([2]))
        let third = try sealer.seal(type: 4, payload: Data([3]))

        var opener = RecordOpener(key: keys.receive)
        XCTAssertThrowsError(try opener.open(body: second.dropFirst(4))) {
            XCTAssertEqual($0 as? RecordError, .unexpectedSequence(expected: 0, received: 1))
        }
        _ = try opener.open(body: first.dropFirst(4))
        XCTAssertThrowsError(try opener.open(body: first.dropFirst(4))) {
            XCTAssertEqual($0 as? RecordError, .unexpectedSequence(expected: 1, received: 0))
        }
        XCTAssertThrowsError(try opener.open(body: third.dropFirst(4)))
        XCTAssertEqual(try opener.open(body: second.dropFirst(4)).payload, Data([2]))
    }

    func testRejectsTamperingAndWrongDirectionKey() throws {
        var sealer = RecordSealer(key: keys.receive)
        let record = try sealer.seal(type: 1, payload: Data("{}".utf8))

        for index in [4, 12, record.count - 1] {  // sequence, ciphertext, tag
            var tampered = record
            tampered[index] ^= 0x80
            var opener = RecordOpener(key: keys.receive)
            XCTAssertThrowsError(try opener.open(body: tampered.dropFirst(4)), "byte \(index)")
            XCTAssertEqual(opener.expectedSequence, 0, "a rejected record must not advance the sequence")
        }

        var wrongDirection = RecordOpener(key: keys.send)
        XCTAssertThrowsError(try wrongDirection.open(body: record.dropFirst(4))) {
            XCTAssertEqual($0 as? RecordError, .authenticationFailed)
        }
    }

    func testLengthPrefixBoundsAreCheckedBeforeAllocation() {
        func prefix(_ value: UInt32) -> Data { withUnsafeBytes(of: value.bigEndian) { Data($0) } }
        XCTAssertNil(RecordFormat.bodyLength(fromPrefix: prefix(0)))
        XCTAssertNil(RecordFormat.bodyLength(fromPrefix: prefix(24)))
        XCTAssertEqual(RecordFormat.bodyLength(fromPrefix: prefix(25)), 25)
        XCTAssertEqual(RecordFormat.bodyLength(fromPrefix: prefix(8_388_633)), 8_388_633)
        XCTAssertNil(RecordFormat.bodyLength(fromPrefix: prefix(8_388_634)))
        XCTAssertNil(RecordFormat.bodyLength(fromPrefix: prefix(.max)))
        XCTAssertNil(RecordFormat.bodyLength(fromPrefix: Data([0, 0, 25])))
    }

    func testPayloadLimitMatchesMaximumRecordLength() throws {
        var sealer = RecordSealer(key: keys.send)
        let largest = try sealer.seal(type: 2, payload: Data(count: RecordFormat.maximumPayload))
        XCTAssertEqual(RecordFormat.bodyLength(fromPrefix: largest.prefix(4)), RecordFormat.maximumLength)
        XCTAssertThrowsError(try sealer.seal(type: 2, payload: Data(count: RecordFormat.maximumPayload + 1))) {
            XCTAssertEqual($0 as? RecordError, .payloadTooLarge)
        }
    }

    func testEmptyPayloadIsSmallestRecord() throws {
        var sealer = RecordSealer(key: keys.send)
        let record = try sealer.seal(type: 4, payload: Data())
        XCTAssertEqual(record.count, 4 + RecordFormat.minimumLength)
    }
}
